use vstd::prelude::*;

verus! {

/// Reverses a non‐empty vector of characters.
/// 
/// Requires:
///   - a.len() > 0
/// Ensures:
///   - The result has the same length as the input.
///   - For all valid indices i, result[i] == a[a.len() - i - 1].
fn reverse(a: &Vec<char>) -> (b: Vec<char>)
    requires
        a.len() > 0,
    ensures
        b.len() == a.len(),
        forall |i: usize| i < a.len() ==> b[i] == a[a.len() - i - 1],
{
    let n = a.len();
    // Build the reversed vector by pushing characters from the end of `a`.
    let mut b: Vec<char> = Vec::with_capacity(n);
    let mut i: usize = 0;
    // Loop invariant:
    //   - 0 <= i <= n
    //   - b.len() == i
    //   - For all j < i, b[j] == a[n - j - 1]
    //   - We decrease on (n - i) to show termination.
    while i < n
        invariant
            i <= n,
            b.len() == i,
            forall |j: usize| j < i ==> b[j] == a[n - j - 1],
        decreases
            n - i,
    {
        let c = a[n - i - 1];
        b.push(c);
        i = i + 1;
    }
    b
}

} // verus!

